public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the path to ensure it ends with a slash
    if (!path.endsWith("/")) {
        path += "/";
    }

    // Tokenize the relative path
    String[] tokens = relativePath.split("/");
    StringBuilder resultPath = new StringBuilder(path);

    for (String token : tokens) {
        if (token.equals("..")) {
            // Move up one directory
            int lastSlashIndex = resultPath.lastIndexOf("/");
            if (lastSlashIndex != -1) {
                resultPath.setLength(lastSlashIndex);
            }
        } else if (token.equals(".")) {
            // Current directory, do nothing
            continue;
        } else if (!token.isEmpty()) {
            // Append the token to the result path
            resultPath.append(token).append("/");
        }
    }

    // Remove the trailing slash if it exists
    if (resultPath.length() > 1 && resultPath.charAt(resultPath.length() - 1) == '/') {
        resultPath.setLength(resultPath.length() - 1);
    }

    return resultPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    try {
        java.nio.file.Path basePath = java.nio.file.Paths.get(path);
        java.nio.file.Path resolvedPath = basePath.resolve(relativePath);
        return resolvedPath.toString();
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid path or relative path provided", e);
    }
}

