                pathStack.push(component); // Add the component to the path
            }
        }

        // Construct the final path
        StringBuilder resultPath = new StringBuilder();
        while (!pathStack.isEmpty()) {
            resultPath.insert(0, pathStack.pop());
            if (!pathStack.isEmpty()) {
                resultPath.insert(0, "/");
            }
        }

        return resultPath.toString();
    } catch (Exception e) {
        // Handle any unexpected issues gracefully
        throw new IllegalArgumentException("Invalid path or relative path provided", e);
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }
    try {
        java.nio.file.Path basePath = java.nio.file.Paths.get(path);
        java.nio.file.Path relative = java.nio.file.Paths.get(relativePath);
        java.nio.file.Path result = basePath.resolve(relative).normalize();
        return result.toString();
    } catch (Exception e) {
        throw new RuntimeException("Error applying relative path", e);
    }
}

